import { NextResponse } from 'next/server';
import { getSignals, addSignal, calculateStats } from '@/lib/signalStore';

export async function GET() {
  const signals = getSignals();
  const stats = calculateStats(signals);
  return NextResponse.json({ stats, signals });
}

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { symbol, entryPrice, takeProfit, stopLoss, score, conviction } = body;

    if (!symbol || !entryPrice || !takeProfit || !stopLoss) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    const newSignal = addSignal({
      symbol,
      entryPrice,
      takeProfit,
      stopLoss,
      score: score || 0,
      conviction: conviction || 'MEDIUM',
    });

    return NextResponse.json({ success: true, signal: newSignal });
  } catch {
    return NextResponse.json({ error: 'Failed to add signal' }, { status: 500 });
  }
}
